def min_rank(graph):
    n = len(graph)
    A = [[graph[i][j] * graph[k][l] for l in range(n)] for k in range(n) for j in range(n)]

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        rank = 0
        for i in range(min(m, n)):
            if A[i][i] == 0:
                for j in range(i + 1, m):
                    if A[j][i] != 0:
                        A[i], A[j] = A[j], A[i]
                        break
                else:
                    continue
            pivot = Fraction(A[i][i])
            for j in range(n):
                A[i][j] /= pivot
            for j in range(m):
                if j != i and A[j][i] != 0:
                    factor = -A[j][i]
                    for k in range(n):
                        A[j][k] += factor * A[i][k]
            rank += 1
        return rank

    return gaussian_elimination(A)

def resolution_length(graph):
    n = len(graph)
    clauses = []

    def add_clause(clause):
        clauses.append(clause)

    for i in range(n):
        for j in range(i + 1, n):
            if graph[i][j] == 1:
                add_clause([-i - 1, -j - 1])
                add_clause([i + 1, j + 1])
                add_clause([-i - 1, j + 1])
                add_clause([i + 1, -j - 1])

    def is_satisfiable():
        stack = []
        assignment = {}

        def backtrack():
            if len(stack) == len(clauses):
                return True
            literal = next((lit for lit in range(1, n + 1) if lit not in assignment and -lit not in assignment), None)
            if literal is None:
                return False

            stack.append(literal)
            assignment[literal] = True
